import{_ as n,o as s,c as e,a2 as p}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"title":"Architecture"},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md","lastUpdated":1782667185000}'),t={name:"concepts/architecture.md"};function l(i,a,o,r,c,d){return s(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Synapse is organized as layered modules. Each layer builds on the abstractions below it.</p><h2 id="layer-overview" tabindex="-1">Layer Overview <a class="header-anchor" href="#layer-overview" aria-label="Permalink to &quot;Layer Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  ADK (Agent Development Kit)                         │</span></span>
<span class="line"><span>│    ├─ Agent trait                                   │</span></span>
<span class="line"><span>│    ├─ ChatModelAgent (LLM + tool calls + ReAct)      │</span></span>
<span class="line"><span>│    ├─ GraphReActAgent (graph-based orchestration)    │</span></span>
<span class="line"><span>│    └─ MultiAgent                                    │</span></span>
<span class="line"><span>│       ├─ RouterSupervisor (LLM-driven)              │</span></span>
<span class="line"><span>│       ├─ OrchestratorAgent (decompose + parallel)    │</span></span>
<span class="line"><span>│       ├─ HandoffSupervisor (transfer)                │</span></span>
<span class="line"><span>│       └─ HybridSupervisor (router + handoff)         │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Components                                         │</span></span>
<span class="line"><span>│    ├─ Model: OpenAI, Anthropic, custom               │</span></span>
<span class="line"><span>│    ├─ Tool: BaseTool, InvokableTool, StreamableTool  │</span></span>
<span class="line"><span>│    ├─ Document: parser, transformer                 │</span></span>
<span class="line"><span>│    │    ├─ CharacterTextSplitter                     │</span></span>
<span class="line"><span>│    │    ├─ RecursiveCharacterTextSplitter            │</span></span>
<span class="line"><span>│    │    ├─ MarkdownHeaderSplitter                    │</span></span>
<span class="line"><span>│    │    └─ TokenTextSplitter                         │</span></span>
<span class="line"><span>│    ├─ Embedding: OpenAI                              │</span></span>
<span class="line"><span>│    ├─ Indexer: InMemory (and future: pgvector, etc.)│</span></span>
<span class="line"><span>│    └─ Retriever: cosine similarity                   │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Transport (cross-platform HTTP)                     │</span></span>
<span class="line"><span>│    ├─ HttpClient trait                              │</span></span>
<span class="line"><span>│    ├─ ReqwestHttpClient (native)                    │</span></span>
<span class="line"><span>│    └─ WasiHttpClient (wasip2, for WASM sandbox)     │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  MCP (Model Context Protocol)                        │</span></span>
<span class="line"><span>│    ├─ StdioMcpClient (subprocess + JSON-RPC)         │</span></span>
<span class="line"><span>│    └─ HttpMcpClient (HTTP transport)                 │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  A2A (Agent-to-Agent)                                │</span></span>
<span class="line"><span>│    └─ A2A Adapter (over HttpClient)                  │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Schema (shared types)                              │</span></span>
<span class="line"><span>│    └─ Message, Content, ToolInfo, ToolCall, etc.     │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="key-design-principles" tabindex="-1">Key Design Principles <a class="header-anchor" href="#key-design-principles" aria-label="Permalink to &quot;Key Design Principles&quot;">​</a></h2><ol><li><strong>Trait-based composition</strong> — Every major abstraction is a trait, allowing users to plug in custom implementations.</li><li><strong>Async by default</strong> — All I/O is <code>async</code>, using <code>async_trait</code> for object safety.</li><li><strong>Cross-platform</strong> — Same code runs natively and in WASM via conditional <code>cfg(target_arch)</code> dependencies.</li><li><strong>Reuse run loops</strong> — The ReAct loop in <code>ChatModelAgent</code> is reused by RouterSupervisor (tool calls as routing), avoiding duplicated orchestration logic.</li><li><strong>No magic</strong> — Each layer&#39;s behavior is explicit and traceable.</li></ol><h2 id="data-flow-example-a-react-agent" tabindex="-1">Data Flow Example: A ReAct Agent <a class="header-anchor" href="#data-flow-example-a-react-agent" aria-label="Permalink to &quot;Data Flow Example: A ReAct Agent&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Input (Vec&lt;Message&gt;)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[ChatModelAgent::run_loop]</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │  loop (max_iterations):</span></span>
<span class="line"><span>   │   │</span></span>
<span class="line"><span>   │   ▼</span></span>
<span class="line"><span>   │  [LLM.generate(messages, tools)]</span></span>
<span class="line"><span>   │   │  (HTTP call to OpenAI / Anthropic / Neuron)</span></span>
<span class="line"><span>   │   ▼</span></span>
<span class="line"><span>   │  response: Message { tool_calls, content }</span></span>
<span class="line"><span>   │   │</span></span>
<span class="line"><span>   │   ├─ if no tool_calls → return final answer</span></span>
<span class="line"><span>   │   │</span></span>
<span class="line"><span>   │   └─ for each tool_call:</span></span>
<span class="line"><span>   │       │</span></span>
<span class="line"><span>   │       ▼</span></span>
<span class="line"><span>   │      [Tool.invoke(args)]</span></span>
<span class="line"><span>   │       │  - BaseTool, McpTool, A2ATool, etc.</span></span>
<span class="line"><span>   │       │</span></span>
<span class="line"><span>   │       ▼</span></span>
<span class="line"><span>   │      result: String → Message::tool(result, tool_call_id)</span></span>
<span class="line"><span>   │       │</span></span>
<span class="line"><span>   │       └─ continue loop</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Final AgentEvent { output.message, output.action, error? }</span></span></code></pre></div><h2 id="multiagent-coordination" tabindex="-1">MultiAgent Coordination <a class="header-anchor" href="#multiagent-coordination" aria-label="Permalink to &quot;MultiAgent Coordination&quot;">​</a></h2><p>Each MultiAgent pattern has a distinct coordination signal:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Coordinator</th><th>Signal</th><th>Who Decides</th></tr></thead><tbody><tr><td>Router/Supervisor</td><td>LLM (host)</td><td><code>tool_call</code></td><td>Top-level LLM</td></tr><tr><td>Host/Orchestrator</td><td>LLM (host)</td><td><code>tool_call</code> (parallel)</td><td>Top-level LLM</td></tr><tr><td>Conversational Handoff</td><td>None (rule-based)</td><td><code>event.action.transfer_to</code></td><td>Sub-agent</td></tr><tr><td>Hybrid</td><td>LLM + handoff</td><td>both</td><td>LLM picks, sub-agents can transfer</td></tr></tbody></table><p>See <a href="/concepts/multiagent">MultiAgent Concepts</a> for details.</p>`,12)])])}const g=n(t,[["render",l]]);export{u as __pageData,g as default};
